WITH cleaned AS (SELECT *, CAST(balance AS INT) AS balance_int, COALESCE(status, 'OTHER') AS status_clean FROM accounts WHERE status IS DISTINCT FROM 'FROZEN' AND customer_id IS NOT NULL), not_flagged AS (SELECT s.* FROM cleaned s WHERE EXISTS (SELECT 1 FROM transactions c WHERE c.account_id = s.id AND c.txn_time >= s.opened_date)), ranked AS (SELECT *, RANK() OVER (PARTITION BY customer_id, account_type ORDER BY balance_int DESC) AS dedup_rank FROM not_flagged QUALIFY dedup_rank = 1), metrics AS (SELECT *, LEAD(balance_int) OVER w_part AS next_balance_int, LEAD(balance) OVER w_part AS next_balance, LAG(balance) OVER w_part AS prev_balance, ROW_NUMBER() OVER w_part AS event_seq FROM ranked WINDOW w_part AS (PARTITION BY account_type, status ORDER BY balance, id)), not_flagged_accounts AS (SELECT s.* FROM metrics s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.txn_type = 'REFUND')) SELECT * FROM (SELECT customer_id, status, balance FROM not_flagged_accounts) src PIVOT (MAX(balance) FOR status IN ('OPEN', 'CLOSED', 'FROZEN'))
